355:     {
356:         while (true)
357:         {
358:             if (isCancellationRequested && isCancellationRequested()) return false;
359: 
360:             ssize_t ret;
361:             ret = recv(buffer, 1);
362: 
363:             // We read one byte, as needed, all good.
364:             if (ret == 1)
365:             {
366:                 return true;
367:             }
368:             // There is possibly something to be read, try again
369:             else if (ret < 0 && Socket::isWaitNeeded())
370:             {
371:                 // Wait with a 1ms timeout until the socket is ready to read.
372:                 // This way we are not busy looping
373:                 if (isReadyToRead(1) == PollResultType::Error)
374:                 {
375:                     return false;
376:                 }
377:             }
378:             // There was an error during the read, abort
379:             else
380:             {
381:                 return false;
382:             }
383:         }
