210:     void SocketServer::stop()
211:     {
212:         // Stop accepting connections, and close the 'accept' thread
213:         if (_thread.joinable())
214:         {
215:             _stop = true;
216:             // Wake up select
217:             if (!_acceptSelectInterrupt->notify(SelectInterrupt::kCloseRequest))
218:             {
219:                 logError("SocketServer::stop: Cannot wake up from select");
220:             }
221: 
222:             _thread.join();
223:             _stop = false;
224:         }
225: 
226:         // Join all threads and make sure that all connections are terminated
227:         if (_gcThread.joinable())
228:         {
229:             _stopGc = true;
230:             {
231:                 std::lock_guard<std::mutex> lock{ _conditionVariableMutexGC };
232:                 _canContinueGC = true;
233:             }
234:             _conditionVariableGC.notify_one();
235:             _gcThread.join();
236:             _stopGc = false;
237:         }
238: 
239:         _conditionVariable.notify_one();
240: 
241:         // stop() runs again from ~WebSocketServer() and ~SocketServer(), so
242:         // close the listening fd exactly once: a second close of the stale
243:         // number would destroy whatever descriptor another thread has since
244:         // opened with it.
245:         if (_serverFd != -1)
246:         {
247:             Socket::closeSocket(_serverFd);
248:             _serverFd = -1;
249:         }
