258:     //
259:     // join the threads for connections that have been closed
260:     //
261:     // When a connection is closed by a client, the connection state terminated
262:     // field becomes true, and we can use that to know that we can join that thread
263:     // and remove it from our _connectionsThreads data structure (a list).
264:     //
265:     void SocketServer::closeTerminatedThreads()
266:     {
267:         std::lock_guard<std::mutex> lock(_connectionsThreadsMutex);
268:         auto it = _connectionsThreads.begin();
269:         auto itEnd = _connectionsThreads.end();
270: 
271:         while (it != itEnd)
272:         {
273:             auto& connectionState = it->first;
274:             auto& thread = it->second;
275: 
276:             if (!connectionState->isTerminated())
277:             {
278:                 ++it;
279:                 continue;
280:             }
281: 
282:             if (thread.joinable()) thread.join();
283:             it = _connectionsThreads.erase(it);
284:         }
285:     }
