287:     void SocketServer::run()
288:     {
289:         // Set the socket to non blocking mode, so that accept calls are not blocking
290:         SocketConnect::configure(_serverFd);
291: 
292:         // Use a cryptic name to stay within the 16 bytes limit thread name limitation
293:         // $ echo Srv:gc:64000 | wc -c
294:         // 13
295:         setThreadName("Srv:ac:" + std::to_string(_port));
296: 
297:         for (;;)
298:         {
299:             if (_stop) return;
300: 
301:             // Use poll to check whether a new connection is in progress
302:             int timeoutMs = -1;
303: #ifdef _WIN32
304:             // select cannot be interrupted on Windows so we need to pass a small timeout
305:             timeoutMs = 10;
306: #endif
307: 
308:             bool readyToRead = true;
309:             PollResultType pollResult =
310:                 Socket::poll(readyToRead, timeoutMs, _serverFd, _acceptSelectInterrupt);
311: 
312:             if (pollResult == PollResultType::Error)
313:             {
314:                 std::stringstream ss;
315:                 ss << "SocketServer::run() error in select: " << strerror(Socket::getErrno());
316:                 logError(ss.str());
317:                 continue;
318:             }
319: 
320:             if (pollResult != PollResultType::ReadyForRead)
321:             {
322:                 continue;
323:             }
324: 
325:             // Accept a connection.
326:             // Use sockaddr_storage to accommodate both AF_INET and AF_INET6 addresses.
327:             // sockaddr_in is only 16 bytes; sockaddr_in6 is 28 bytes. On Windows, passing
328:             // a too-small buffer to accept() causes WSAEFAULT (error 10014).
329:             struct sockaddr_storage client; // client address information (IPv4 or IPv6)
330:             int clientFd;                   // socket connected to client
331:             socklen_t addressLen = sizeof(client);
332:             memset(&client, 0, sizeof(client));
333: 
334:             if ((clientFd = static_cast<int>(accept(_serverFd, (struct sockaddr*) &client, &addressLen))) < 0)
335:             {
336:                 if (!Socket::isWaitNeeded())
337:                 {
338:                     // FIXME: that error should be propagated
339:                     int err = Socket::getErrno();
340:                     std::stringstream ss;
341:                     ss << "SocketServer::run() error accepting connection: " << err << ", "
342:                        << strerror(err);
343:                     logError(ss.str());
344:                 }
345:                 continue;
346:             }
347: 
348:             if (getConnectedClientsCount() >= _maxConnections)
349:             {
350:                 std::stringstream ss;
351:                 ss << "SocketServer::run() reached max connections = " << _maxConnections << ". "
352:                    << "Not accepting connection";
353:                 logError(ss.str());
354: 
355:                 Socket::closeSocket(clientFd);
356: 
357:                 continue;
358:             }
359: 
360:             // Retrieve connection info, the ip address of the remote peer/client)
361:             std::string remoteIp;
362:             int remotePort;
363: 
364:             if (_addressFamily == AF_INET)
365:             {
366:                 char remoteIp4[INET_ADDRSTRLEN];
367:                 auto* client4 = reinterpret_cast<struct sockaddr_in*>(&client);
368:                 if (ix::inet_ntop(AF_INET, &client4->sin_addr, remoteIp4, INET_ADDRSTRLEN) == nullptr)
369:                 {
370:                     int err = Socket::getErrno();
371:                     std::stringstream ss;
372:                     ss << "SocketServer::run() error calling inet_ntop (ipv4): " << err << ", "
373:                        << strerror(err);
374:                     logError(ss.str());
375: 
376:                     Socket::closeSocket(clientFd);
377: 
378:                     continue;
379:                 }
380: 
381:                 remotePort = ix::network_to_host_short(client4->sin_port);
382:                 remoteIp = remoteIp4;
383:             }
384:             else // AF_INET6
385:             {
386:                 char remoteIp6[INET6_ADDRSTRLEN];
387:                 auto* client6 = reinterpret_cast<struct sockaddr_in6*>(&client);
388:                 if (ix::inet_ntop(AF_INET6, &client6->sin6_addr, remoteIp6, INET6_ADDRSTRLEN) ==
389:                     nullptr)
390:                 {
391:                     int err = Socket::getErrno();
392:                     std::stringstream ss;
393:                     ss << "SocketServer::run() error calling inet_ntop (ipv6): " << err << ", "
394:                        << strerror(err);
395:                     logError(ss.str());
396: 
397:                     Socket::closeSocket(clientFd);
398: 
399:                     continue;
400:                 }
401: 
402:                 remotePort = ix::network_to_host_short(client6->sin6_port);
403:                 remoteIp = remoteIp6;
404:             }
405: 
406:             std::shared_ptr<ConnectionState> connectionState;
407:             if (_connectionStateFactory)
408:             {
409:                 connectionState = _connectionStateFactory();
410:             }
411:             connectionState->setOnSetTerminatedCallback([this] { onSetTerminatedCallback(); });
412:             connectionState->setRemoteIp(remoteIp);
413:             connectionState->setRemotePort(remotePort);
414: 
415:             if (_stop) return;
416: 
417:             // create socket
418:             std::string errorMsg;
419:             bool tls = _socketTLSOptions.tls;
420:             auto socket = createSocket(tls, clientFd, errorMsg, _socketTLSOptions);
421: 
422:             if (socket == nullptr)
423:             {
424:                 logError("SocketServer::run() cannot create socket: " + errorMsg);
425:                 Socket::closeSocket(clientFd);
426:                 continue;
427:             }
428: 
429:             // Set the socket to non blocking mode + other tweaks
430:             SocketConnect::configure(clientFd);
431: 
432:             if (!socket->accept(errorMsg))
433:             {
434:                 logError("SocketServer::run() tls accept failed: " + errorMsg);
435:                 Socket::closeSocket(clientFd);
436:                 continue;
437:             }
438: 
439:             // Launch the handleConnection work asynchronously in its own thread.
440:             std::lock_guard<std::mutex> lock(_connectionsThreadsMutex);
441:             _connectionsThreads.push_back(std::make_pair(
442:                 connectionState,
443:                 std::thread(
444:                     &SocketServer::handleConnection, this, std::move(socket), connectionState)));
445:         }
446:     }
