454:     void SocketServer::runGC()
455:     {
456:         // Use a cryptic name to stay within the 16 bytes limit thread name limitation
457:         // $ echo Srv:gc:64000 | wc -c
458:         // 13
459:         setThreadName("Srv:gc:" + std::to_string(_port));
460: 
461:         for (;;)
462:         {
463:             // Garbage collection to shutdown/join threads for closed connections.
464:             closeTerminatedThreads();
465: 
466:             // We quit this thread if all connections are closed and we received
467:             // a stop request by setting _stopGc to true.
468:             if (_stopGc && getConnectionsThreadsCount() == 0)
469:             {
470:                 break;
471:             }
472: 
473:             // Unless we are stopping the server, wait for a connection
474:             // to be terminated to run the threads GC, instead of busy waiting
475:             // with a sleep
476:             if (!_stopGc)
477:             {
478:                 std::unique_lock<std::mutex> lock(_conditionVariableMutexGC);
479:                 if(!_canContinueGC) {
480:                     _conditionVariableGC.wait(lock, [this]{ return _canContinueGC; });
481:                 }
482:                 _canContinueGC = false;
483:             }
484:         }
485:     }
