492:     void SocketServer::onSetTerminatedCallback()
493:     {
494:         // a connection got terminated, we can run the connection thread GC,
495:         // so wake up the thread responsible for that
496:         {
497:             std::lock_guard<std::mutex> lock{ _conditionVariableMutexGC };
498:             _canContinueGC = true;
499:         }
500:         _conditionVariableGC.notify_one();
501:     }
