152:     std::string SocketOpenSSL::getSSLError(int ret)
153:     {
154:         unsigned long e;
155: 
156:         int err = SSL_get_error(_ssl_connection, ret);
157: 
158:         if (err == SSL_ERROR_WANT_CONNECT || err == SSL_ERROR_WANT_ACCEPT)
159:         {
160:             return "OpenSSL failed - connection failure";
161:         }
162:         else if (err == SSL_ERROR_WANT_X509_LOOKUP)
163:         {
164:             return "OpenSSL failed - x509 error";
165:         }
166:         else if (err == SSL_ERROR_SYSCALL)
167:         {
168:             e = ERR_get_error();
169:             if (e > 0)
170:             {
171:                 std::string errMsg("OpenSSL failed - ");
172:                 errMsg += ERR_error_string(e, nullptr);
173:                 return errMsg;
174:             }
175:             else if (e == 0 && ret == 0)
176:             {
177:                 return "OpenSSL failed - received early EOF";
178:             }
179:             else
180:             {
181:                 return "OpenSSL failed - underlying BIO reported an I/O error";
182:             }
183:         }
184:         else if (err == SSL_ERROR_SSL)
185:         {
186:             e = ERR_get_error();
187:             std::string errMsg("OpenSSL failed - ");
188:             errMsg += ERR_error_string(e, nullptr);
189:             return errMsg;
190:         }
191:         else if (err == SSL_ERROR_NONE)
192:         {
193:             return "OpenSSL failed - err none";
194:         }
195:         else if (err == SSL_ERROR_ZERO_RETURN)
196:         {
197:             return "OpenSSL failed - err zero return";
198:         }
199:         else
200:         {
201:             return "OpenSSL failed - unknown error";
202:         }
203:     }
