228:     bool SocketOpenSSL::openSSLAddCARootsFromString(const std::string roots)
229:     {
230:         // Create certificate store
231:         X509_STORE* certificate_store = SSL_CTX_get_cert_store(_ssl_context);
232:         if (certificate_store == nullptr) return false;
233: 
234:         // Configure to allow intermediate certs
235:         X509_STORE_set_flags(certificate_store,
236:                              X509_V_FLAG_TRUSTED_FIRST | X509_V_FLAG_PARTIAL_CHAIN);
237: 
238:         // Create a new buffer and populate it with the roots
239:         BIO* buffer = BIO_new_mem_buf((void*) roots.c_str(), static_cast<int>(roots.length()));
240:         if (buffer == nullptr) return false;
241: 
242:         // Read each root in the buffer and add to the certificate store
243:         bool success = true;
244:         size_t number_of_roots = 0;
245: 
246:         while (true)
247:         {
248:             // Read the next root in the buffer
249:             X509* root = PEM_read_bio_X509_AUX(buffer, nullptr, nullptr, (void*) "");
250:             if (root == nullptr)
251:             {
252:                 // No more certs left in the buffer, we're done.
253:                 ERR_clear_error();
254:                 break;
255:             }
256: 
257:             // Try adding the root to the certificate store
258:             ERR_clear_error();
259:             if (!X509_STORE_add_cert(certificate_store, root))
260:             {
261:                 // Failed to add. If the error is unrelated to the x509 lib or the cert already
262:                 // exists, we're safe to continue.
263:                 unsigned long error = ERR_get_error();
264:                 if (ERR_GET_LIB(error) != ERR_LIB_X509 ||
265:                     ERR_GET_REASON(error) != X509_R_CERT_ALREADY_IN_HASH_TABLE)
266:                 {
267:                     // Failed. Clean up and bail.
268:                     success = false;
269:                     X509_free(root);
270:                     break;
271:                 }
272:             }
273: 
274:             // Clean up and loop
275:             X509_free(root);
276:             number_of_roots++;
277:         }
278: 
279:         // Clean up buffer
280:         BIO_free(buffer);
281: 
282:         // Make sure we loaded at least one certificate.
283:         if (number_of_roots == 0) success = false;
284: 
285:         return success;
286:     }
