308:     bool SocketOpenSSL::openSSLCheckServerCert(SSL* ssl,
309: #if OPENSSL_VERSION_NUMBER < 0x10100000L
310:                                                const std::string& hostname,
311: #else
312:                                                const std::string& /* hostname */,
313: #endif
314:                                                std::string& errMsg)
315:     {
316:         X509* server_cert = SSL_get_peer_certificate(ssl);
317:         if (server_cert == nullptr)
318:         {
319:             errMsg = "OpenSSL failed - peer didn't present a X509 certificate.";
320:             return false;
321:         }
322: 
323: #if OPENSSL_VERSION_NUMBER < 0x10100000L
324:         // Check server name
325:         bool hostname_verifies_ok = false;
326:         STACK_OF(GENERAL_NAME)* san_names = (STACK_OF(GENERAL_NAME)*) X509_get_ext_d2i(
327:             (X509*) server_cert, NID_subject_alt_name, NULL, NULL);
328:         if (san_names)
329:         {
330:             for (int i = 0; i < sk_GENERAL_NAME_num(san_names); i++)
331:             {
332:                 const GENERAL_NAME* sk_name = sk_GENERAL_NAME_value(san_names, i);
333:                 if (sk_name->type == GEN_DNS)
334:                 {
335:                     char* name = (char*) ASN1_STRING_data(sk_name->d.dNSName);
336:                     if ((size_t) ASN1_STRING_length(sk_name->d.dNSName) == strlen(name) &&
337:                         checkHost(hostname, name))
338:                     {
339:                         hostname_verifies_ok = true;
340:                         break;
341:                     }
342:                 }
343:             }
344:         }
345:         sk_GENERAL_NAME_pop_free(san_names, GENERAL_NAME_free);
346: 
347:         if (!hostname_verifies_ok)
348:         {
349:             int cn_pos = X509_NAME_get_index_by_NID(
350:                 X509_get_subject_name((X509*) server_cert), NID_commonName, -1);
351:             if (cn_pos >= 0)
352:             {
353:                 X509_NAME_ENTRY* cn_entry =
354:                     X509_NAME_get_entry(X509_get_subject_name((X509*) server_cert), cn_pos);
355: 
356:                 if (cn_entry != nullptr)
357:                 {
358:                     ASN1_STRING* cn_asn1 = X509_NAME_ENTRY_get_data(cn_entry);
359:                     char* cn = (char*) ASN1_STRING_data(cn_asn1);
360: 
361:                     if ((size_t) ASN1_STRING_length(cn_asn1) == strlen(cn) &&
362:                         checkHost(hostname, cn))
363:                     {
364:                         hostname_verifies_ok = true;
365:                     }
366:                 }
367:             }
368:         }
369: 
370:         if (!hostname_verifies_ok)
371:         {
372:             errMsg = "OpenSSL failed - certificate was issued for a different domain.";
373:             return false;
374:         }
375: #endif
376: 
377:         X509_free(server_cert);
378:         return true;
379:     }
