381:     bool SocketOpenSSL::openSSLClientHandshake(const std::string& host,
382:                                                std::string& errMsg,
383:                                                const CancellationRequest& isCancellationRequested)
384:     {
385:         while (true)
386:         {
387:             if (_ssl_connection == nullptr || _ssl_context == nullptr)
388:             {
389:                 return false;
390:             }
391: 
392:             if (isCancellationRequested())
393:             {
394:                 errMsg = "Cancellation requested";
395:                 return false;
396:             }
397: 
398:             ERR_clear_error();
399:             int connect_result = SSL_connect(_ssl_connection);
400:             if (connect_result == 1)
401:             {
402:                 if (_tlsOptions.disable_hostname_validation)
403:                 {
404:                     return true;
405:                 }
406: 
407:                 return openSSLCheckServerCert(_ssl_connection, host, errMsg);
408:             }
409:             int reason = SSL_get_error(_ssl_connection, connect_result);
410: 
411:             bool rc = false;
412:             if (reason == SSL_ERROR_WANT_READ || reason == SSL_ERROR_WANT_WRITE)
413:             {
414:                 rc = true;
415:             }
416:             else
417:             {
418:                 errMsg = getSSLError(connect_result);
419:                 rc = false;
420:             }
421: 
422:             if (!rc)
423:             {
424:                 return false;
425:             }
426:         }
427:     }
