464:     bool SocketOpenSSL::handleTLSOptions(std::string& errMsg)
465:     {
466:         ERR_clear_error();
467:         if (_tlsOptions.hasCertAndKey())
468:         {
469:             if (SSL_CTX_use_certificate_chain_file(_ssl_context, _tlsOptions.certFile.c_str()) != 1)
470:             {
471:                 auto sslErr = ERR_get_error();
472:                 errMsg = "OpenSSL failed - SSL_CTX_use_certificate_chain_file(\"" +
473:                          _tlsOptions.certFile + "\") failed: ";
474:                 errMsg += ERR_error_string(sslErr, nullptr);
475:             }
476:             else if (SSL_CTX_use_PrivateKey_file(
477:                          _ssl_context, _tlsOptions.keyFile.c_str(), SSL_FILETYPE_PEM) != 1)
478:             {
479:                 auto sslErr = ERR_get_error();
480:                 errMsg = "OpenSSL failed - SSL_CTX_use_PrivateKey_file(\"" + _tlsOptions.keyFile +
481:                          "\") failed: ";
482:                 errMsg += ERR_error_string(sslErr, nullptr);
483:             }
484:             else if (!SSL_CTX_check_private_key(_ssl_context))
485:             {
486:                 auto sslErr = ERR_get_error();
487:                 errMsg = "OpenSSL failed - cert/key mismatch(\"" + _tlsOptions.certFile + ", " +
488:                          _tlsOptions.keyFile + "\")";
489:                 errMsg += ERR_error_string(sslErr, nullptr);
490:             }
491:         }
492: 
493:         ERR_clear_error();
494:         if (!_tlsOptions.isPeerVerifyDisabled())
495:         {
496:             if (_tlsOptions.isUsingSystemDefaults())
497:             {
498: #ifdef _WIN32
499:                 if (!loadWindowsSystemCertificates(_ssl_context, errMsg))
500:                 {
501:                     return false;
502:                 }
503: #else
504:                 if (SSL_CTX_set_default_verify_paths(_ssl_context) == 0)
505:                 {
506:                     auto sslErr = ERR_get_error();
507:                     errMsg = "OpenSSL failed - SSL_CTX_default_verify_paths loading failed: ";
508:                     errMsg += ERR_error_string(sslErr, nullptr);
509:                     return false;
510:                 }
511: #endif
512:             }
513:             else
514:             {
515:                 if (_tlsOptions.isUsingInMemoryCAs())
516:                 {
517:                     // Load from memory
518:                     openSSLAddCARootsFromString(_tlsOptions.caFile);
519:                 }
520:                 else
521:                 {
522:                     if (SSL_CTX_load_verify_locations(
523:                             _ssl_context, _tlsOptions.caFile.c_str(), NULL) != 1)
524:                     {
525:                         auto sslErr = ERR_get_error();
526:                         errMsg = "OpenSSL failed - SSL_CTX_load_verify_locations(\"" +
527:                                  _tlsOptions.caFile + "\") failed: ";
528:                         errMsg += ERR_error_string(sslErr, nullptr);
529:                         return false;
530:                     }
531:                 }
532:             }
533: 
534:             SSL_CTX_set_verify(_ssl_context,
535:                                SSL_VERIFY_PEER,
536:                                [](int preverify, X509_STORE_CTX*) -> int { return preverify; });
537:             SSL_CTX_set_verify_depth(_ssl_context, 4);
538:         }
539:         else
540:         {
541:             SSL_CTX_set_verify(_ssl_context, SSL_VERIFY_NONE, nullptr);
542:         }
543: 
544:         if (_tlsOptions.isUsingDefaultCiphers())
545:         {
546:             if (SSL_CTX_set_cipher_list(_ssl_context, kDefaultCiphers.c_str()) != 1)
547:             {
548:                 auto sslErr = ERR_get_error();
549:                 errMsg = "OpenSSL failed - SSL_CTX_set_cipher_list(\"" + kDefaultCiphers +
550:                          "\") failed: ";
551:                 errMsg += ERR_error_string(sslErr, nullptr);
552:                 return false;
553:             }
554:         }
555:         else if (SSL_CTX_set_cipher_list(_ssl_context, _tlsOptions.ciphers.c_str()) != 1)
556:         {
557:             auto sslErr = ERR_get_error();
558:             errMsg = "OpenSSL failed - SSL_CTX_set_cipher_list(\"" + _tlsOptions.ciphers +
559:                      "\") failed: ";
560:             errMsg += ERR_error_string(sslErr, nullptr);
561:             return false;
562:         }
563: 
564:         return true;
565:     }
