567:     bool SocketOpenSSL::accept(std::string& errMsg)
568:     {
569:         bool handshakeSuccessful = false;
570:         {
571:             std::lock_guard<std::mutex> lock(_mutex);
572: 
573:             if (!_openSSLInitializationSuccessful)
574:             {
575:                 errMsg = "OPENSSL_init_ssl failure";
576:                 return false;
577:             }
578: 
579:             if (_sockfd == -1)
580:             {
581:                 return false;
582:             }
583: 
584:             {
585:                 const SSL_METHOD* method = SSLv23_server_method();
586:                 if (method == nullptr)
587:                 {
588:                     errMsg = "SSLv23_server_method failure";
589:                     _ssl_context = nullptr;
590:                 }
591:                 else
592:                 {
593:                     _ssl_method = method;
594: 
595:                     _ssl_context = SSL_CTX_new(_ssl_method);
596:                     if (_ssl_context)
597:                     {
598:                         SSL_CTX_set_mode(_ssl_context, SSL_MODE_ENABLE_PARTIAL_WRITE);
599:                         SSL_CTX_set_mode(_ssl_context, SSL_MODE_ACCEPT_MOVING_WRITE_BUFFER);
600:                         SSL_CTX_set_options(_ssl_context,
601:                                             SSL_OP_ALL | SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3);
602:                     }
603:                 }
604:             }
605: 
606:             if (_ssl_context == nullptr)
607:             {
608:                 return false;
609:             }
610: 
611:             ERR_clear_error();
612:             if (_tlsOptions.hasCertAndKey())
613:             {
614:                 if (SSL_CTX_use_certificate_chain_file(_ssl_context,
615:                                                        _tlsOptions.certFile.c_str()) != 1)
616:                 {
617:                     auto sslErr = ERR_get_error();
618:                     errMsg = "OpenSSL failed - SSL_CTX_use_certificate_chain_file(\"" +
619:                              _tlsOptions.certFile + "\") failed: ";
620:                     errMsg += ERR_error_string(sslErr, nullptr);
621:                 }
622:                 else if (SSL_CTX_use_PrivateKey_file(
623:                              _ssl_context, _tlsOptions.keyFile.c_str(), SSL_FILETYPE_PEM) != 1)
624:                 {
625:                     auto sslErr = ERR_get_error();
626:                     errMsg = "OpenSSL failed - SSL_CTX_use_PrivateKey_file(\"" +
627:                              _tlsOptions.keyFile + "\") failed: ";
628:                     errMsg += ERR_error_string(sslErr, nullptr);
629:                 }
630:             }
631: 
632: 
633:             ERR_clear_error();
634:             if (!_tlsOptions.isPeerVerifyDisabled())
635:             {
636:                 if (_tlsOptions.isUsingSystemDefaults())
637:                 {
638:                     if (SSL_CTX_set_default_verify_paths(_ssl_context) == 0)
639:                     {
640:                         auto sslErr = ERR_get_error();
641:                         errMsg = "OpenSSL failed - SSL_CTX_default_verify_paths loading failed: ";
642:                         errMsg += ERR_error_string(sslErr, nullptr);
643:                     }
644:                 }
645:                 else
646:                 {
647:                     if (_tlsOptions.isUsingInMemoryCAs())
648:                     {
649:                         // Load from memory
650:                         openSSLAddCARootsFromString(_tlsOptions.caFile);
651:                     }
652:                     else
653:                     {
654:                         const char* root_ca_file = _tlsOptions.caFile.c_str();
655:                         STACK_OF(X509_NAME) * rootCAs;
656:                         rootCAs = SSL_load_client_CA_file(root_ca_file);
657:                         if (rootCAs == NULL)
658:                         {
659:                             auto sslErr = ERR_get_error();
660:                             errMsg = "OpenSSL failed - SSL_load_client_CA_file('" +
661:                                      _tlsOptions.caFile + "') failed: ";
662:                             errMsg += ERR_error_string(sslErr, nullptr);
663:                         }
664:                         else
665:                         {
666:                             SSL_CTX_set_client_CA_list(_ssl_context, rootCAs);
667:                             if (SSL_CTX_load_verify_locations(
668:                                     _ssl_context, root_ca_file, nullptr) != 1)
669:                             {
670:                                 auto sslErr = ERR_get_error();
671:                                 errMsg = "OpenSSL failed - SSL_CTX_load_verify_locations(\"" +
672:                                          _tlsOptions.caFile + "\") failed: ";
673:                                 errMsg += ERR_error_string(sslErr, nullptr);
674:                             }
675:                         }
676:                     }
677:                 }
678: 
679:                 SSL_CTX_set_verify(
680:                     _ssl_context, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, nullptr);
681:                 SSL_CTX_set_verify_depth(_ssl_context, 4);
682:             }
683:             else
684:             {
685:                 SSL_CTX_set_verify(_ssl_context, SSL_VERIFY_NONE, nullptr);
686:             }
687:             if (_tlsOptions.isUsingDefaultCiphers())
688:             {
689:                 if (SSL_CTX_set_cipher_list(_ssl_context, kDefaultCiphers.c_str()) != 1)
690:                 {
691:                     return false;
692:                 }
693:             }
694:             else if (SSL_CTX_set_cipher_list(_ssl_context, _tlsOptions.ciphers.c_str()) != 1)
695:             {
696:                 return false;
697:             }
698: 
699:             _ssl_connection = SSL_new(_ssl_context);
700:             if (_ssl_connection == nullptr)
701:             {
702:                 errMsg = "OpenSSL failed to connect";
703:                 SSL_CTX_free(_ssl_context);
704:                 _ssl_context = nullptr;
705:                 return false;
706:             }
707: 
708:             SSL_set_ecdh_auto(_ssl_connection, 1);
709: 
710:             SSL_set_fd(_ssl_connection, _sockfd);
711: 
712:             handshakeSuccessful = openSSLServerHandshake(errMsg);
713:         }
714: 
715:         if (!handshakeSuccessful)
716:         {
717:             close();
718:             return false;
719:         }
720: 
721:         return true;
722:     }
