724:     bool SocketOpenSSL::connect(const std::string& host,
725:                                 int port,
726:                                 std::string& errMsg,
727:                                 const CancellationRequest& isCancellationRequested)
728:     {
729:         bool handshakeSuccessful = false;
730:         {
731:             std::lock_guard<std::mutex> lock(_mutex);
732: 
733:             if (!_openSSLInitializationSuccessful)
734:             {
735:                 errMsg = "OPENSSL_init_ssl failure";
736:                 return false;
737:             }
738: 
739:             _sockfd = SocketConnect::connect(host, port, errMsg, isCancellationRequested);
740:             if (_sockfd == -1) return false;
741: 
742:             _ssl_context = openSSLCreateContext(errMsg);
743:             if (_ssl_context == nullptr)
744:             {
745:                 return false;
746:             }
747: 
748:             if (!handleTLSOptions(errMsg))
749:             {
750:                 return false;
751:             }
752: 
753:             _ssl_connection = SSL_new(_ssl_context);
754:             if (_ssl_connection == nullptr)
755:             {
756:                 errMsg = "OpenSSL failed to connect";
757:                 SSL_CTX_free(_ssl_context);
758:                 _ssl_context = nullptr;
759:                 return false;
760:             }
761:             SSL_set_fd(_ssl_connection, _sockfd);
762: 
763:             // SNI support
764:             SSL_set_tlsext_host_name(_ssl_connection, host.c_str());
765: 
766: #if OPENSSL_VERSION_NUMBER >= 0x10002000L
767:             // Support for server name verification
768:             // (The docs say that this should work from 1.0.2, and is the default from
769:             // 1.1.0, but it does not. To be on the safe side, the manual test
770:             // below is enabled for all versions prior to 1.1.0.)
771:             if (!_tlsOptions.disable_hostname_validation)
772:             {
